	getgenv().CobaltInitialized = false
	getgenv().Cobalt = nil

	if wax.shared.Communicator then wax.shared.Communicator:Destroy() end
	wax.shared.DexBridge.Unmount()

	wax.shared.Unloaded = true

	if identity then setthreadidentity(identity) end
end

