	if not item then
		item = findUniqueByValue(value)
		if item and not Constants.EnumTypes[typeId] then
			Constants.EnumTypes[typeId] = item.EnumType
		end
	end

	return {
		Result = item or value,
		Offset = newOffset,
	}
end

