	return {
		InvokeId = invokeId,
		IsResponse = isResponse,
		RequestRef = requestRef,
		IsError = false,
		Error = nil,
		Arguments = {
			Values = parsed.Values,
			Count = parsed.Count,
		},
		Offset = parsed.Offset,
	}
