local function MatchesPacketId(packetIds: number | { number }, packetId: number): boolean
	if typeof(packetIds) == "number" then
		return packetIds == packetId
	end

	return table.find(packetIds, packetId) ~= nil
end

export type RakNetMessage = {
	AsBuffer: buffer,
	AsString: string,
	AsArray: { number },
	Size: number,
	PacketId: number,
	Priority: number,
